def policy(obs, P):
    x = obs[0]
    v = obs[1]
    th = obs[2]
    thd = obs[3]
    if th < P['th_neg']:
        if thd > P['thd_vhi']:
            score = P['w_th']*th + P['w_thd_vhi']*thd + P['w_v']*v + P['w_x']*x + P['b']
        else:
            score = P['w_th']*th + P['w_thd']*thd + P['w_v']*v + P['w_x']*x + P['b']
    elif th < P['th_small']:
        if thd > P['thd_mid']:
            score = P['w_th_s']*th + P['w_thd_s']*thd + P['w_v_s']*v + P['w_x']*x + P['b_s']
        else:
            score = P['w_th']*th + P['w_thd']*thd + P['w_v']*v + P['w_x']*x + P['b']
    else:
        score = P['w_th']*th + P['w_thd']*thd + P['w_v']*v + P['w_x']*x + P['b']
    return 1 if score > 0 else 0
